"package main

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"time"
)

func main() {
	fmt.Println("=== Testing Antigravity CLI (agy) Subprocess Execution ===")

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	// Run agy --version
	cmdVer := exec.CommandContext(ctx, "agy", "--version")
	verOut, err := cmdVer.CombinedOutput()
	if err != nil {
		fmt.Printf("Failed to run agy --version: %v\n", err)
	} else {
		fmt.Printf("Detected Antigravity CLI Version: %s\n", string(bytes.TrimSpace(verOut)))
	}

	// Test non-interactive print mode
	prompt := "Reply strictly in JSON: {\"status\":\"ok\",\"role\":\"Product Analyst\"}"
	cmdPrint := exec.CommandContext(ctx, "agy", "-p", prompt, "--output-format", "json", "--disable-slash-commands")

	var stdoutBuf, stderrBuf bytes.Buffer
	cmdPrint.Stdout = &stdoutBuf
	cmdPrint.Stderr = &stderrBuf

	start := time.Now()
	err = cmdPrint.Run()
	elapsed := time.Since(start)

	if err != nil {
		fmt.Printf("agy execution returned error: %v\n", err)
		fmt.Printf("Stderr: %s\n", stderrBuf.String())
	} else {
		fmt.Printf("agy execution succeeded in %v!\n", elapsed)
		fmt.Printf("Stdout: %s\n", stdoutBuf.String())
	}
}
