"package main

import (
	"fmt"

	"github.com/zalando/go-keyring"
)

func main() {
	fmt.Println("=== Testing OS Secure Credential Store (zalando/go-keyring) ===")

	service := "AIRequirementsStudioTest"
	user := "gemini_api_key"
	dummySecret := "sk-test-secret-12345"

	// Set credential
	err := keyring.Set(service, user, dummySecret)
	if err != nil {
		fmt.Printf("Failed to set credential in keyring: %v\n", err)
		return
	}

	// Retrieve credential
	secret, err := keyring.Get(service, user)
	if err != nil {
		fmt.Printf("Failed to get credential from keyring: %v\n", err)
		return
	}

	if secret == dummySecret {
		fmt.Println("Successfully stored and retrieved secret from Windows Credential Store!")
	} else {
		fmt.Printf("Secret mismatch! Expected %s, got %s\n", dummySecret, secret)
	}

	// Clean up
	_ = keyring.Delete(service, user)
	fmt.Println("Cleaned up test secret.")
}
