	defer cancel()

	status := map[string]any{
		"active_provider": "antigravity-cli",
		"providers": []map[string]any{
			{
				"id":        "antigravity-cli",
				"name":      "Antigravity CLI",
				"type":      "cli",
				"available": false,
				"version":   "unknown",
			},
		},
	}

	if s.agyAdapter != nil {
		err := s.agyAdapter.CheckAvailability(ctx)
		provList := status["providers"].([]map[string]any)
		if err == nil {
			provList[0]["available"] = true
			provList[0]["version"] = "1.5.5"
		} else {
			provList[0]["error"] = err.Error()
		}
	}

	return status, nil
}

