	query := `INSERT INTO validation_runs (id, project_id, validation_type, status, created_at)
	          VALUES (?, ?, ?, ?, ?)`
	now := time.Now().UTC()
	_, err := r.db.ExecContext(ctx, query, id, projectID, valType, status, now)
