"package opencode

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os/exec"
	"strings"
	"time"

	"ai-requirements-studio/internal/ai"
	"ai-requirements-studio/internal/domain"
)

type Adapter struct {
	executablePath string
	baseURL        string
	model          string
	apiKey         string
	httpClient     *http.Client
}

func NewAdapter(customPath, baseURL, model, apiKey string) *Adapter {
	if customPath == "" {
		customPath = "opencode"
	}
	if model == "" {
		model = "default"
	}
	return &Adapter{
		executablePath: customPath,
		baseURL:        strings.TrimRight(baseURL, "/"),
		model:          model,
		apiKey:         apiKey,
		httpClient:     &http.Client{Timeout: 90 * time.Second},
	}
}

func (a *Adapter) ID() string {
	return "opencode"
}

func (a *Adapter) Name() string {
	return "OpenCode / OpenAI-Compatible"
}

func (a *Adapter) Type() domain.ProviderType {
	if a.baseURL != "" {
		return domain.ProviderCloud
	}
	return domain.ProviderCLI
}

func (a *Adapter) SetConfig(baseURL, model, apiKey string) {
	a.baseURL = strings.TrimRight(baseURL, "/")
	if model != "" {
		a.model = model
	}
