	o.mu.Lock()
	defer o.mu.Unlock()
	if id != "" {
		if _, exists := o.providers[id]; !exists {
			return fmt.Errorf("fallback provider %s not registered", id)
		}
	}
	o.fallbackProvider = id
	o.fallbackEnabled = enabled
	return nil
}

