122: func ParseDiscoveryOutput(content string) (*DiscoveryResult, error) {
123: 	clean := strings.TrimSpace(content)
124: 
125: 	// Strip potential markdown code fences: ```json ... ```
126: 	if strings.HasPrefix(clean, "```") {
127: 		idx := strings.Index(clean, "\n")
128: 		if idx != -1 {
129: 			clean = clean[idx+1:]
130: 		}
131: 		if strings.HasSuffix(clean, "```") {
132: 			clean = strings.TrimSuffix(clean, "```")
133: 		}
134: 		clean = strings.TrimSpace(clean)
135: 	}
136: 
137: 	var res DiscoveryResult
138: 	if err := json.Unmarshal([]byte(clean), &res); err != nil {
139: 		// Fallback gracefully: treat raw text as conversational reply without structured items
140: 		return &DiscoveryResult{
141: 			Reply: clean,
142: 			Role:  "Product Analyst",
143: 		}, nil
144: 	}
145: 
